L=extract(s); used=set(); out=s
for pos,x in sorted(L,key=lambda t:-t[0]):
    if x in TR:
        out=out[:pos]+TR[x]+out[pos+len(x):]; used.add(x)
un=[k for k in TR if k not in used]
for k in un: print("UNUSED",k[:70])
out,c=re.subn(r'(<meta name="app-version" content="2026-11-24)([a-z])(")',lambda m:m.group(1)+chr(ord(m.group(2))+1)+m.group(3),out,count=1)
